import numpy as np
def equation(t, x, v, params):
    p=params
    return (p[0] + p[1]*t + p[2]*np.tanh(v) + p[3]*np.exp(-x)*v**3 + p[4]*x*np.exp(-v)
            + p[5]*np.sqrt(t) + p[6]/v + p[7]*np.exp(-v) + p[8]*np.exp(-x)*v**2 + p[9]*np.tanh(x))
